<script setup>
import { computed, ref, onMounted, onBeforeUnmount, nextTick } from "vue";
import { X, LockKeyhole, Check, Sparkles } from "@lucide/vue";
import { api, jsonBody } from "../api";
const props=defineProps({state:{type:Object,required:true},name:{type:String,default:"同学"}});
const emit=defineEmits(["close","saved"]);
const dialog=ref(null);let previousFocus;
function keepFocus(event){if(event.key!=='Tab')return;const items=[...dialog.value.querySelectorAll('button:not(:disabled)')];if(!items.length)return;const first=items[0],last=items.at(-1);if(event.shiftKey&&document.activeElement===first){event.preventDefault();last.focus();}else if(!event.shiftKey&&document.activeElement===last){event.preventDefault();first.focus();}}
onMounted(async()=>{previousFocus=document.activeElement;await nextTick();dialog.value?.querySelector('button')?.focus();});
onBeforeUnmount(()=>previousFocus?.focus());
const draft=ref({...props.state.selection});const busy=ref(false),error=ref("");
const groups=[{type:"frame",label:"头像框"},{type:"title",label:"专属称号"},{type:"background",label:"背景皮肤"}];
const title=computed(()=>props.state.options.find(o=>o.type==='title'&&o.code===draft.value.title)?.name);
async function save(){if(busy.value)return;busy.value=true;error.value="";try{emit('saved',await api('/public/rankings/student-style',{method:'PUT',body:jsonBody(draft.value)}));}catch(e){error.value=e.message||'装扮保存失败，请重试';}finally{busy.value=false;}}
</script>
<template><Teleport to="body"><div class="ui-dialog-backdrop style-backdrop" @click.self="!busy&&emit('close')" @keydown.esc="!busy&&emit('close')"><section ref="dialog" @keydown="keepFocus" class="ui-modal style-dialog" role="dialog" aria-modal="true" aria-labelledby="style-title" tabindex="-1"><header><div><h2 id="style-title"><Sparkles :size="19"/>我的装扮</h2><p>随荣耀段位解锁，不消耗积分；头像框与称号会在同老师排行榜展示</p></div><button autofocus class="icon-button" aria-label="关闭装扮" :disabled="busy" @click="emit('close')"><X :size="18"/></button></header><div class="ui-modal-body"><div class="style-preview" :class="[`preview-${draft.background}`,`frame-${draft.frame}`]"><span class="style-avatar">{{ name.slice(-2) }}</span><strong>{{ name }}</strong><small>{{ title }}</small></div><section v-for="group in groups" :key="group.type" class="style-group"><h3>{{ group.label }}</h3><div class="style-options"><button v-for="option in state.options.filter(o=>o.type===group.type)" :key="option.code" type="button" :disabled="busy||option.level>state.level" :aria-pressed="draft[group.type]===option.code" :class="{chosen:draft[group.type]===option.code}" @click="draft[group.type]=option.code"><LockKeyhole v-if="option.level>state.level" :size="14"/><Check v-else-if="draft[group.type]===option.code" :size="14"/><span>{{ option.name }}<small>{{ option.level>state.level?`LV.${option.level} 解锁`:'已解锁' }}</small></span></button></div></section><p v-if="error" role="alert" class="style-error">{{ error }}</p></div><footer><button class="button button-quiet" :disabled="busy" @click="emit('close')">取消</button><button class="button button-primary" :disabled="busy" @click="save">{{ busy?'保存中…':'保存装扮' }}</button></footer></section></div></Teleport></template>
<style scoped>
.style-backdrop{z-index:180}.style-dialog{width:min(540px,100%)}.style-dialog h2{display:flex;align-items:center;gap:8px}.style-preview{display:grid;justify-items:center;gap:8px;padding:22px;border:1px solid #304865;border-radius:12px;background:linear-gradient(145deg,#152b47,#0c172b);color:#e8f2ff}.style-avatar{display:grid;place-items:center;width:60px;height:60px;border:2px solid #7e96b7;border-radius:50%;background:#20334f;color:#e8f2ff;font-weight:700}.style-preview small{color:#89a7cf}.preview-aurora{background:radial-gradient(ellipse at top right,#194c52,transparent),#12213c}.preview-orbit{background:repeating-radial-gradient(ellipse at bottom left,transparent 0 27px,#304263 28px 29px),#111b36}.frame-cyan .style-avatar{border-color:#55dfff;box-shadow:0 0 16px #38c9e638}.frame-prism .style-avatar{border-color:#b799ff;box-shadow:0 0 0 4px #9670ff30}.frame-regal .style-avatar{border-color:#ffdb87;box-shadow:0 0 0 4px #ffdb8730,0 0 20px #ffdb8730}.frame-nova .style-avatar{border-color:#9bf5ed;box-shadow:0 0 0 4px #9bf5ed20,0 0 22px #9bf5ed38}.style-group h3{margin:20px 0 10px;font-size:13px;color:#d9e7fb}.style-options{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:8px}.style-options button{display:flex;align-items:center;gap:8px;min-height:56px;padding:10px 12px;border:1px solid #344d6b;border-radius:8px;background:#142640;color:#c9dcf5;text-align:left;cursor:pointer;font:inherit;font-size:12px}.style-options .chosen{border-color:#50d6ee;background:#183948;color:#7ae7f8}.style-options small{display:block;margin-top:4px;color:#92a8c6;font-size:10px}.style-options button:disabled{opacity:.5;cursor:default}.style-error{color:#ff9baa}.style-options button:focus-visible{outline:2px solid #55dfff;outline-offset:2px}
</style>
